  // A trainer's own profile only ever stores a birthday (not a raw age
  // number the way client_profiles does) — this derives the age
  // recalcBmrAndTargets needs from it, whole years only, correctly handling
  // "birthday hasn't happened yet this year."
  function ageFromBirthday(iso) {
    if (!iso) return null;
    const b = new Date(iso + "T00:00:00");
    if (isNaN(b.getTime())) return null;
    const now = new Date();
    let age = now.getFullYear() - b.getFullYear();
    const beforeBirthdayThisYear = now.getMonth() < b.getMonth() || (now.getMonth() === b.getMonth() && now.getDate() < b.getDate());
    if (beforeBirthdayThisYear) age--;
    return age;
  }

