  // BMR from body composition — Katch-McArdle (370 + 21.6 * lean mass) when
  // a lean mass is known, since it's driven by the tissue that actually
  // burns calories at rest rather than total weight, so it doesn't
  // undercount a muscular client or overcount a leaner one the way a
  // weight-only formula does. Falls back to the standard Mifflin-St Jeor
  // formula (weight/height/age/gender only) when no body-fat%/muscle-mass
  // was given — same formula this app has always used for that case.
  function bmrFromBody(weightKg, heightCm, age, gender, leanMassKg) {
    if (leanMassKg != null) return 370 + 21.6 * leanMassKg;
    return gender === "Female" ? 10 * weightKg + 6.25 * heightCm - 5 * age - 161
      : gender === "Male" ? 10 * weightKg + 6.25 * heightCm - 5 * age + 5
      : 10 * weightKg + 6.25 * heightCm - 5 * age - 78;
  }

