  function computeDashboardStats(entries, payments) {
    const today = todayISO();
    const monthPrefix = today.slice(0, 7);
    const todaySet = new Set();
    const monthSet = new Set();
    entries.forEach((x) => {
      if (!x.date) return;
      // Sept 18 2026: was keyed by clientName + date — two clients sharing
      // a first name (normal pooling 17 trainers' rosters together) counted
      // as ONE session instead of two, silently undercounting the numbers
      // this feeds up to the Dashboard/higher management. Every real
      // account has a real, unique clientId, so that's the key whenever
      // it's there; clientName stays as the fallback only for old/self-log
      // entries that genuinely have no clientId, same as elsewhere in the app.
      const who = x.clientId || x.clientName;
      if (x.date === today) todaySet.add(who + "|" + x.date);
      if (x.date.slice(0, 7) === monthPrefix) monthSet.add(who + "|" + x.date);
    });
    let totalPaid = 0, monthPaid = 0;
    payments.forEach((p) => {
      const amt = Number(p.amount) || 0;
      totalPaid += amt;
      if (p.paid_on && p.paid_on.slice(0, 7) === monthPrefix) monthPaid += amt;
    });
    return { sessionsToday: todaySet.size, sessionsMonth: monthSet.size, totalPaid, monthPaid };
  }

  // Per-exercise strength trend: one top-set weight per day, across every session ever
  // logged for that exercise (independent of the week/all-time toggle, which is about
  // muscle volume, not long-run trend) — each date stays its own point, never merged.
  function computeExerciseProgression(entries) {
    // Same case/whitespace normalization as computeMaxWeightByExercise and
    // computePersonalRecords — grouped by exerciseGifKey so "Bench Press" and
    // "Bench press" plot as one continuous trend line, not two broken ones.
    const byExercise = {};
    entries.forEach((x) => {
      const key = exerciseGifKey(x.exercise);
      if (!key) return;
      const topWeight = Math.max(0, ...x.sets.map((s) => Number(s.weight) || 0));
      (byExercise[key] = byExercise[key] || { exercise: x.exercise, muscleGroup: x.muscleGroup, byDate: {} });
      byExercise[key].exercise = x.exercise || byExercise[key].exercise; // most-recent casing wins for display
      byExercise[key].muscleGroup = x.muscleGroup || byExercise[key].muscleGroup;
      const cur = byExercise[key].byDate[x.date];
      byExercise[key].byDate[x.date] = cur === undefined ? topWeight : Math.max(cur, topWeight);
    });
    return Object.values(byExercise).map((info) => {
      const points = Object.entries(info.byDate).sort((a, b) => (a[0] < b[0] ? -1 : 1)).map(([date, weight]) => ({ date, weight }));
      return { exercise: info.exercise, muscleGroup: info.muscleGroup || "Full Body", points };
    }).filter((x) => x.points.length >= 2)
      .sort((a, b) => b.points.length - a.points.length || a.exercise.localeCompare(b.exercise));
  }

  function blobToBase64(blob) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const result = String(reader.result || "");
        resolve(result.split(",")[1] || "");
      };
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
  }

